const ASSETS = {"/index.html":{"body":"<!doctype html>\n<html lang=\"ja\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"referrer\" content=\"no-referrer\">\n  <title>9月通常授業アンケート</title>\n  <link rel=\"stylesheet\" href=\"./styles.css\">\n</head>\n<body>\n  <main class=\"app\">\n    <header class=\"hero\">\n      <p>進学塾SOIL 出町校</p>\n      <h1>9月通常授業アンケート</h1>\n      <span id=\"pageLead\">来られる曜日・時間を選んで送信してください。</span>\n    </header>\n\n    <section id=\"accessState\" class=\"panel access-state\">\n      <h2 id=\"accessTitle\">回答ページを確認しています</h2>\n      <p id=\"accessMessage\">少しお待ちください。</p>\n    </section>\n\n    <section id=\"studentView\" class=\"panel view\">\n      <div class=\"panel-title\">\n        <h2>生徒用</h2>\n        <p>9月からの通常授業日時を決めるためのアンケートです。最初はすべて〇にしています。来れない日時に×をして、8/16（日）までに提出してください。期限までの提出が難しい場合はお知らせください。よろしくお願いします。</p>\n      </div>\n\n      <form id=\"studentForm\" class=\"form\">\n        <div class=\"respondent-identity\" aria-label=\"回答者\">\n          <span id=\"studentIdentityGrade\" class=\"identity-meta\"></span>\n          <strong id=\"studentIdentityName\"></strong>\n        </div>\n\n        <div class=\"grid-card\">\n          <div class=\"grid-label\">〇＝通塾できる / ×＝通塾できない</div>\n          <div id=\"studentGrid\" class=\"slot-grid student-grid\"></div>\n        </div>\n\n        <div id=\"studentReview\" class=\"own-answer\"></div>\n\n        <label>\n          補足\n          <textarea id=\"studentMemo\" rows=\"3\" placeholder=\"備考欄\"></textarea>\n        </label>\n\n        <button class=\"primary\" type=\"submit\">生徒回答を送信</button>\n      </form>\n    </section>\n\n    <section id=\"teacherView\" class=\"panel view\">\n      <div class=\"panel-title\">\n        <h2>講師用</h2>\n        <p>9月からの勤務日時を決めるため、来れる日時をタップして提出をお願いします。期限は8/16（日）までです。もし期限内の提出が厳しければお知らせください。</p>\n      </div>\n\n      <form id=\"teacherForm\" class=\"form\">\n        <div class=\"respondent-identity\" aria-label=\"回答者\">\n          <span class=\"identity-meta\">講師</span>\n          <strong id=\"teacherIdentityName\"></strong>\n        </div>\n\n        <div class=\"grid-card\">\n          <div class=\"grid-label\">勤務可能な曜日</div>\n          <div id=\"teacherGrid\" class=\"teacher-days\"></div>\n        </div>\n\n        <div id=\"teacherReview\" class=\"own-answer\"></div>\n\n        <label>\n          補足\n          <textarea id=\"teacherMemo\" rows=\"3\" placeholder=\"勤務に関する補足があれば入力してください。\"></textarea>\n        </label>\n\n        <button class=\"primary\" type=\"submit\">講師回答を送信</button>\n      </form>\n    </section>\n\n    <p id=\"statusMessage\" class=\"status\" aria-live=\"polite\"></p>\n  </main>\n\n  <script src=\"./app.js\"></script>\n</body>\n</html>\n","type":"text/html; charset=utf-8"},"/student.html":{"body":"<!doctype html>\n<html lang=\"ja\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>生徒用 | 9月通常授業アンケート</title>\n  <script>location.replace(\"./index.html\" + location.search);</script>\n</head>\n<body>\n  <a href=\"./index.html\">アンケートを開く</a>\n</body>\n</html>\n","type":"text/html; charset=utf-8"},"/teacher.html":{"body":"<!doctype html>\n<html lang=\"ja\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>講師用 | 9月通常授業アンケート</title>\n  <script>location.replace(\"./index.html\" + location.search);</script>\n</head>\n<body>\n  <a href=\"./index.html\">アンケートを開く</a>\n</body>\n</html>\n","type":"text/html; charset=utf-8"},"/admin.html":{"body":"<!doctype html>\n<html lang=\"ja\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>回答ページへ移動 | 9月通常授業アンケート</title>\n  <script>location.replace(\"./index.html\" + location.search);</script>\n</head>\n<body>\n  <a href=\"./index.html\">アンケートを開く</a>\n</body>\n</html>\n","type":"text/html; charset=utf-8"},"/styles.css":{"body":":root {\n  --ink: #09224a;\n  --muted: #65758b;\n  --line: #d7e2ef;\n  --panel: #ffffff;\n  --bg: #eef4fb;\n  --blue: #17457f;\n  --blue-soft: #e8f1fb;\n  --green: #0c7a5b;\n  --green-soft: #e8f8f1;\n  --red: #b42318;\n  --shadow: 0 18px 42px rgba(18, 42, 77, 0.12);\n}\n\n* {\n  box-sizing: border-box;\n}\n\nhtml {\n  max-width: 100%;\n  overflow-x: hidden;\n}\n\nbody {\n  margin: 0;\n  color: var(--ink);\n  background: linear-gradient(180deg, #f6f9fd 0%, var(--bg) 100%);\n  font-family: \"Yu Gothic\", \"Yu Gothic UI\", \"Meiryo\", sans-serif;\n  max-width: 100%;\n  overflow-x: hidden;\n}\n\nbutton,\ninput,\nselect,\ntextarea {\n  font: inherit;\n  font-size: 16px;\n}\n\n.app {\n  width: min(1100px, calc(100% - 28px));\n  margin: 0 auto;\n  padding: 22px 0 42px;\n}\n\n.hero {\n  padding: 22px 4px 16px;\n}\n\n.hero p {\n  margin: 0 0 8px;\n  color: var(--blue);\n  font-weight: 700;\n}\n\n.hero h1 {\n  margin: 0;\n  font-size: clamp(28px, 5vw, 42px);\n  letter-spacing: 0;\n}\n\n.hero span {\n  display: block;\n  margin-top: 10px;\n  color: var(--muted);\n  line-height: 1.7;\n}\n\n.tabs {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 8px;\n  position: sticky;\n  top: 0;\n  z-index: 10;\n  padding: 8px 0;\n  background: rgba(246, 249, 253, 0.94);\n  backdrop-filter: blur(8px);\n}\n\nbody[data-page=\"student\"] .tabs,\nbody[data-page=\"teacher\"] .tabs {\n  display: none;\n}\n\n.tab,\n.admin-actions button,\n.primary,\n.master-form button,\n.master-row button {\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  background: #fff;\n  color: var(--ink);\n  min-height: 48px;\n  padding: 10px 14px;\n  font-weight: 700;\n  cursor: pointer;\n  text-align: center;\n  text-decoration: none;\n}\n\n.tab.active,\n.primary,\n.admin-actions button:first-child {\n  background: var(--blue);\n  border-color: var(--blue);\n  color: #fff;\n}\n\n.panel {\n  display: none;\n  margin-top: 14px;\n  padding: 22px;\n  border: 1px solid var(--line);\n  border-radius: 10px;\n  background: var(--panel);\n  box-shadow: var(--shadow);\n}\n\n.panel.active {\n  display: block;\n}\n\n.panel-title {\n  margin-bottom: 18px;\n}\n\n.panel-title h2 {\n  margin: 0 0 6px;\n  font-size: 26px;\n}\n\n.panel-title p {\n  margin: 0;\n  color: var(--muted);\n}\n\n.form {\n  display: grid;\n  gap: 16px;\n}\n\n.access-state {\n  display: block;\n  text-align: center;\n}\n\n.access-state[hidden] {\n  display: none;\n}\n\n.access-state h2 {\n  margin: 0 0 8px;\n  font-size: 24px;\n}\n\n.access-state p {\n  margin: 0;\n  color: var(--muted);\n  line-height: 1.7;\n}\n\n.access-state.error {\n  border-color: #f0b4ae;\n}\n\n.respondent-identity {\n  display: grid;\n  grid-template-columns: auto minmax(0, 1fr);\n  gap: 12px;\n  align-items: center;\n  min-height: 64px;\n  padding: 12px 14px;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  background: #f6f9fd;\n}\n\n.respondent-identity strong {\n  min-width: 0;\n  font-size: 20px;\n  overflow-wrap: anywhere;\n}\n\n.identity-meta {\n  padding: 6px 9px;\n  border-radius: 6px;\n  background: var(--blue-soft);\n  color: var(--blue);\n  font-size: 14px;\n  font-weight: 800;\n}\n\n.student-select-row {\n  display: grid;\n  grid-template-columns: minmax(130px, 180px) minmax(240px, 1fr);\n  gap: 14px;\n  align-items: end;\n}\n\nlabel {\n  display: grid;\n  gap: 8px;\n  font-weight: 700;\n}\n\ninput,\nselect,\ntextarea {\n  width: 100%;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  padding: 12px 14px;\n  background: #fff;\n  color: var(--ink);\n}\n\ninput[readonly] {\n  background: #f6f9fd;\n}\n\ntextarea {\n  resize: vertical;\n}\n\n.grid-card {\n  border: 1px solid var(--line);\n  border-radius: 10px;\n  overflow: hidden;\n}\n\n.grid-label {\n  padding: 12px 14px;\n  background: #f6f9fd;\n  font-weight: 800;\n}\n\n.slot-grid {\n  display: grid;\n  grid-template-columns: 110px repeat(5, 1fr);\n}\n\n.slot-grid > div {\n  min-height: 58px;\n  border: 0;\n  border-top: 1px solid var(--line);\n  border-left: 1px solid var(--line);\n  background: #fff;\n}\n\n.slot-grid > div:nth-child(6n + 1) {\n  border-left: 0;\n}\n\n.head,\n.time {\n  display: grid;\n  place-items: center;\n  background: #f6f9fd !important;\n  font-weight: 800;\n  text-align: center;\n}\n\n.slot {\n  display: grid;\n  place-items: center;\n  min-height: 58px;\n  border: 0;\n  border-top: 1px solid var(--line);\n  border-left: 1px solid var(--line);\n  background: #fff;\n  color: var(--red);\n  font-weight: 800;\n  cursor: pointer;\n}\n\n.slot:focus-visible,\n.teacher-days button:focus-visible {\n  outline: 3px solid rgba(23, 69, 127, 0.22);\n  outline-offset: -3px;\n}\n\n.slot.selected,\n.teacher-days button.selected {\n  background: var(--green-soft);\n  color: var(--green);\n  box-shadow: inset 0 0 0 2px var(--green);\n}\n\n.slot.unavailable {\n  background: #fff7f7;\n  box-shadow: inset 0 0 0 1px #fecaca;\n}\n\n.own-answer {\n  display: none;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  overflow: hidden;\n  background: #fbfdff;\n}\n\n.own-answer:not(:empty) {\n  display: block;\n}\n\n.own-answer-title {\n  padding: 10px 12px;\n  background: #f6f9fd;\n  font-weight: 800;\n}\n\n.own-answer table {\n  width: 100%;\n  border-collapse: collapse;\n}\n\n.own-answer th,\n.own-answer td {\n  padding: 9px 12px;\n  border-top: 1px solid var(--line);\n  text-align: left;\n  vertical-align: top;\n}\n\n.own-answer th {\n  width: 92px;\n  color: var(--muted);\n  font-weight: 800;\n}\n\n.teacher-days {\n  display: grid;\n  grid-template-columns: repeat(6, 1fr);\n}\n\n.teacher-days button {\n  display: grid;\n  gap: 4px;\n  place-items: center;\n  min-height: 58px;\n  border: 0;\n  border-top: 1px solid var(--line);\n  border-left: 1px solid var(--line);\n  background: #fff;\n  padding: 12px 8px;\n  color: var(--muted);\n  font-weight: 800;\n  cursor: pointer;\n}\n\n.teacher-days button strong {\n  min-height: 22px;\n  color: transparent;\n}\n\n.teacher-days button.selected strong {\n  color: var(--green);\n}\n\n.teacher-days button:first-child {\n  border-left: 0;\n}\n\n.teacher-days small {\n  color: inherit;\n  font-size: 12px;\n}\n\n.primary {\n  width: 100%;\n  margin-top: 4px;\n  font-size: 18px;\n}\n\n.status {\n  min-height: 28px;\n  margin: 14px 0 0;\n  font-weight: 800;\n}\n\n.status.ok {\n  color: var(--green);\n}\n\n.status.error {\n  color: var(--red);\n}\n\n.admin-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 16px;\n  margin-bottom: 18px;\n}\n\n.admin-link-card {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 16px;\n  margin: 0 0 18px;\n  padding: 16px;\n  border: 1px solid var(--line);\n  border-radius: 10px;\n  background: #fbfdff;\n}\n\n.admin-link-card h3 {\n  margin: 0 0 6px;\n}\n\n.admin-link-card p {\n  margin: 0;\n  color: var(--muted);\n}\n\n.admin-link-buttons {\n  display: flex;\n  gap: 10px;\n  flex-wrap: wrap;\n}\n\n.admin-link-buttons a {\n  display: inline-grid;\n  place-items: center;\n  min-height: 44px;\n  padding: 10px 14px;\n  border: 1px solid var(--blue);\n  border-radius: 8px;\n  color: var(--blue);\n  background: #fff;\n  font-weight: 800;\n  text-decoration: none;\n}\n\n.admin-card {\n  border: 1px solid var(--line);\n  border-radius: 10px;\n  padding: 16px;\n  background: #fbfdff;\n}\n\n.admin-card h3 {\n  margin: 0 0 12px;\n}\n\n.master-form {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) 120px 90px;\n  gap: 8px;\n  margin-bottom: 12px;\n}\n\n#teacherMasterForm {\n  grid-template-columns: minmax(0, 1fr) 90px;\n}\n\n.master-list {\n  display: grid;\n  gap: 8px;\n  max-height: 220px;\n  overflow: auto;\n  padding: 8px;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  background: #f6f9fd;\n}\n\n.master-row {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 10px;\n  padding: 10px 12px;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  background: #fff;\n}\n\n.master-row small {\n  color: var(--muted);\n  font-weight: 700;\n}\n\n.master-row button {\n  min-height: 34px;\n  padding: 5px 10px;\n  color: var(--red);\n}\n\n.admin-actions {\n  display: flex;\n  gap: 10px;\n  flex-wrap: wrap;\n  margin: 20px 0 14px;\n}\n\n.results-summary {\n  display: flex;\n  gap: 10px;\n  flex-wrap: wrap;\n  margin-bottom: 14px;\n}\n\n.results-summary span {\n  padding: 8px 12px;\n  border-radius: 999px;\n  background: var(--blue-soft);\n  font-weight: 800;\n}\n\n.results-area {\n  display: grid;\n  gap: 20px;\n}\n\n.result-table-wrap {\n  max-width: 100%;\n  overflow-x: auto;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n}\n\n.result-table,\n.matrix-table {\n  width: 100%;\n  border-collapse: collapse;\n  table-layout: fixed;\n  min-width: 0;\n}\n\n.matrix-table {\n  font-size: 13px;\n}\n\n.student-matrix {\n  min-width: 1040px;\n}\n\n.teacher-matrix {\n  min-width: 780px;\n}\n\n.result-table th,\n.result-table td,\n.matrix-table th,\n.matrix-table td {\n  border-bottom: 1px solid var(--line);\n  border-right: 1px solid var(--line);\n  padding: 8px 6px;\n  text-align: left;\n  vertical-align: middle;\n  overflow-wrap: anywhere;\n  word-break: keep-all;\n}\n\n.result-table th,\n.matrix-table th {\n  background: #f6f9fd;\n  font-weight: 800;\n}\n\n.matrix-table th {\n  line-height: 1.35;\n  text-align: center;\n}\n\n.student-matrix th:first-child,\n.student-matrix td:first-child {\n  width: 82px;\n}\n\n.student-matrix th:nth-child(2),\n.student-matrix td:nth-child(2) {\n  width: 70px;\n}\n\n.student-matrix th:nth-child(3),\n.student-matrix td:nth-child(3) {\n  width: 50px;\n}\n\n.student-matrix th:last-child,\n.student-matrix td:last-child {\n  width: 58px;\n  text-align: center;\n}\n\n.student-matrix th:nth-last-child(2),\n.student-matrix td:nth-last-child(2) {\n  width: 70px;\n}\n\n.teacher-matrix th:first-child,\n.teacher-matrix td:first-child {\n  width: 82px;\n}\n\n.teacher-matrix th:nth-child(2),\n.teacher-matrix td:nth-child(2) {\n  width: 120px;\n}\n\n.teacher-matrix th:last-child,\n.teacher-matrix td:last-child {\n  width: 58px;\n  text-align: center;\n}\n\n.teacher-matrix th:nth-last-child(2),\n.teacher-matrix td:nth-last-child(2) {\n  width: 90px;\n}\n\n.matrix-table .mark {\n  text-align: center;\n  font-size: 22px;\n  font-weight: 900;\n  color: var(--green);\n}\n\n.matrix-action {\n  text-align: center;\n}\n\n.result-table th:first-child,\n.result-table td:first-child {\n  width: 96px;\n}\n\n.result-table th:nth-child(2),\n.result-table td:nth-child(2),\n.result-table th:nth-child(3),\n.result-table td:nth-child(3) {\n  width: 72px;\n}\n\n.result-table th:last-child,\n.result-table td:last-child {\n  width: 72px;\n  text-align: center;\n}\n\n.danger-small {\n  min-height: 34px;\n  padding: 5px 10px;\n  border-color: #fecaca;\n  color: var(--red);\n  background: #fff7f7;\n}\n\n.empty {\n  margin: 0;\n  color: var(--muted);\n}\n\n@media (max-width: 760px) {\n  .app {\n    width: 100%;\n    padding: 10px 8px 28px;\n  }\n\n  body[data-page=\"admin\"] .app {\n    padding-left: 2px;\n    padding-right: 2px;\n  }\n\n  .hero {\n    padding: 16px 4px 12px;\n  }\n\n  .hero h1 {\n    font-size: 30px;\n  }\n\n  .hero span {\n    font-size: 16px;\n  }\n\n  .panel {\n    padding: 14px 12px;\n    border-radius: 8px;\n  }\n\n  body[data-page=\"admin\"] .panel {\n    padding-left: 4px;\n    padding-right: 4px;\n  }\n\n  .panel-title h2 {\n    font-size: 28px;\n  }\n\n  .panel-title p {\n    font-size: 16px;\n    line-height: 1.7;\n  }\n\n  .tabs {\n    gap: 6px;\n    padding: 6px 0;\n  }\n\n  .tab {\n    min-width: 0;\n    min-height: 46px;\n    padding: 9px 6px;\n    font-size: 15px;\n  }\n\n  .slot-grid {\n    grid-template-columns: 72px repeat(5, minmax(0, 1fr));\n  }\n\n  .slot-grid > div,\n  .slot-grid .slot {\n    min-height: 56px;\n    padding: 6px 3px;\n    font-size: 14px;\n  }\n\n  .slot-grid .head {\n    font-size: 14px;\n  }\n\n  .slot-grid .time {\n    font-size: 13px;\n    line-height: 1.25;\n  }\n\n  .teacher-days {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n  }\n\n  .teacher-days button:nth-child(2n + 1) {\n    border-left: 0;\n  }\n\n  .teacher-days button {\n    min-height: 64px;\n    padding: 10px 6px;\n  }\n\n  .admin-grid {\n    grid-template-columns: 1fr;\n  }\n\n  .admin-link-card {\n    align-items: stretch;\n    flex-direction: column;\n  }\n\n  .admin-link-buttons a {\n    flex: 1 1 160px;\n  }\n\n  .master-form,\n  #teacherMasterForm {\n    grid-template-columns: 1fr;\n  }\n\n  .student-select-row {\n    grid-template-columns: 1fr;\n  }\n\n  .result-table-wrap {\n    overflow-x: auto;\n  }\n\n  .matrix-table {\n    font-size: 10px;\n    line-height: 1.15;\n  }\n\n  .student-matrix {\n    min-width: 460px;\n  }\n\n  .teacher-matrix {\n    min-width: 390px;\n  }\n\n  .matrix-table th,\n  .matrix-table td {\n    padding: 4px 1px;\n    white-space: nowrap;\n  }\n\n  .student-matrix th:first-child,\n  .student-matrix td:first-child,\n  .teacher-matrix th:first-child,\n  .teacher-matrix td:first-child {\n    width: 36px;\n  }\n\n  .student-matrix th:nth-child(2),\n  .student-matrix td:nth-child(2),\n  .teacher-matrix th:nth-child(2),\n  .teacher-matrix td:nth-child(2) {\n    width: 44px;\n  }\n\n  .student-matrix th:nth-child(3),\n  .student-matrix td:nth-child(3) {\n    width: 24px;\n  }\n\n  .student-matrix th:last-child,\n  .student-matrix td:last-child,\n  .teacher-matrix th:last-child,\n  .teacher-matrix td:last-child {\n    width: 26px;\n  }\n\n  .student-matrix th:nth-last-child(2),\n  .student-matrix td:nth-last-child(2),\n  .teacher-matrix th:nth-last-child(2),\n  .teacher-matrix td:nth-last-child(2) {\n    width: 28px;\n  }\n\n  .matrix-table td:first-child,\n  .matrix-table td:nth-child(2),\n  .matrix-table td:nth-last-child(2) {\n    overflow: hidden;\n    text-overflow: ellipsis;\n  }\n\n  .matrix-table .mark {\n    font-size: 14px;\n  }\n\n  .danger-small {\n    min-height: 24px;\n    padding: 2px 4px;\n    font-size: 10px;\n  }\n}\n\n@media (max-width: 420px) {\n  .app {\n    padding-left: 6px;\n    padding-right: 6px;\n  }\n\n  .panel {\n    padding-left: 10px;\n    padding-right: 10px;\n  }\n\n  .slot-grid {\n    grid-template-columns: 66px repeat(5, minmax(0, 1fr));\n  }\n\n  .slot-grid > div,\n  .slot-grid .slot {\n    min-height: 54px;\n    font-size: 13px;\n  }\n\n  .slot-grid .time {\n    font-size: 12px;\n  }\n}\n","type":"text/css; charset=utf-8"},"/app.js":{"body":"const SUPABASE = {\n  url: \"https://dlymqxjxandoxponairu.supabase.co\",\n  functionName: \"september-survey-response\",\n};\n\nconst weekdays = [\n  { id: \"mon\", label: \"月曜日\" },\n  { id: \"tue\", label: \"火曜日\" },\n  { id: \"wed\", label: \"水曜日\" },\n  { id: \"thu\", label: \"木曜日\" },\n  { id: \"fri\", label: \"金曜日\" },\n];\n\nconst teacherDays = [\n  { id: \"mon\", label: \"月曜日\", time: \"19:00-22:00\" },\n  { id: \"tue\", label: \"火曜日\", time: \"19:00-22:00\" },\n  { id: \"wed\", label: \"水曜日\", time: \"19:00-22:00\" },\n  { id: \"thu\", label: \"木曜日\", time: \"19:00-22:00\" },\n  { id: \"fri\", label: \"金曜日\", time: \"19:00-22:00\" },\n  { id: \"sat\", label: \"土曜日\", time: \"17:00-22:00\" },\n];\n\nconst studentSlots = [\n  { id: \"19\", label: \"19:00-19:50\" },\n  { id: \"20\", label: \"20:00-20:50\" },\n  { id: \"21\", label: \"21:00-21:50\" },\n];\n\nconst localSubmissionPrefix = \"septemberSurveySubmission\";\nconst sessionTokenKey = \"septemberSurveyAccessToken\";\nconst tokenPattern = /^[a-f0-9]{64}$/i;\n\nconst pageLeads = {\n  student: \"最初はすべて〇にしています。来れない日時に×をして提出してください。よろしくお願いします。\",\n  teacher: \"9月からの勤務日時を決めるため、来れる日時をタップして提出をお願いします。期限は8/16（日）までです。もし期限内の提出が厳しければお知らせください。\",\n};\n\nconst state = {\n  page: null,\n  profile: null,\n  token: \"\",\n  tokenStorageKey: \"\",\n  student: new Set(),\n  teacher: new Set(),\n};\n\nconst elements = {\n  pageLead: document.querySelector(\"#pageLead\"),\n  accessState: document.querySelector(\"#accessState\"),\n  accessTitle: document.querySelector(\"#accessTitle\"),\n  accessMessage: document.querySelector(\"#accessMessage\"),\n  views: [...document.querySelectorAll(\".view\")],\n  status: document.querySelector(\"#statusMessage\"),\n  studentForm: document.querySelector(\"#studentForm\"),\n  teacherForm: document.querySelector(\"#teacherForm\"),\n  studentIdentityName: document.querySelector(\"#studentIdentityName\"),\n  studentIdentityGrade: document.querySelector(\"#studentIdentityGrade\"),\n  teacherIdentityName: document.querySelector(\"#teacherIdentityName\"),\n  studentGrid: document.querySelector(\"#studentGrid\"),\n  teacherGrid: document.querySelector(\"#teacherGrid\"),\n  studentReview: document.querySelector(\"#studentReview\"),\n  teacherReview: document.querySelector(\"#teacherReview\"),\n};\n\nfunction functionUrl(query = \"\") {\n  return `${SUPABASE.url}/functions/v1/${SUPABASE.functionName}${query}`;\n}\n\nfunction showStatus(message, type = \"ok\") {\n  elements.status.textContent = message;\n  elements.status.className = `status ${type}`;\n}\n\nfunction showAccessState(title, message, type = \"\") {\n  elements.accessState.hidden = false;\n  elements.accessState.className = `panel access-state ${type}`.trim();\n  elements.accessTitle.textContent = title;\n  elements.accessMessage.textContent = message;\n  elements.views.forEach((panel) => panel.classList.remove(\"active\"));\n  elements.pageLead.textContent = \"専用の回答URLを確認しています。\";\n}\n\nfunction showPage(page) {\n  state.page = page;\n  document.body.dataset.page = page;\n  elements.accessState.hidden = true;\n  elements.views.forEach((panel) => panel.classList.toggle(\"active\", panel.id === `${page}View`));\n  elements.pageLead.textContent = pageLeads[page];\n  showStatus(\"\");\n}\n\nfunction renderStudentGrid() {\n  const cells = [\n    '<div class=\"head\">時間</div>',\n    ...weekdays.map((day) => `<div class=\"head\">${day.label.replace(\"曜日\", \"\")}</div>`),\n  ];\n\n  for (const slot of studentSlots) {\n    cells.push(`<div class=\"time\">${slot.label}</div>`);\n    for (const day of weekdays) {\n      const key = `${day.id}_${slot.id}`;\n      const available = state.student.has(key);\n      cells.push(`<button class=\"slot ${available ? \"selected\" : \"unavailable\"}\" type=\"button\" data-student-slot=\"${key}\">${available ? \"〇\" : \"×\"}</button>`);\n    }\n  }\n\n  elements.studentGrid.innerHTML = cells.join(\"\");\n}\n\nfunction allStudentSlotKeys() {\n  return weekdays.flatMap((day) => studentSlots.map((slot) => `${day.id}_${slot.id}`));\n}\n\nfunction selectAllStudentSlots() {\n  state.student = new Set(allStudentSlotKeys());\n}\n\nfunction renderTeacherGrid() {\n  elements.teacherGrid.innerHTML = teacherDays.map((day) => `\n    <button class=\"${state.teacher.has(day.id) ? \"selected\" : \"\"}\" type=\"button\" data-teacher-day=\"${day.id}\">\n      <span>${day.label}</span>\n      <small>${day.time}</small>\n      <strong>${state.teacher.has(day.id) ? \"〇\" : \"\"}</strong>\n    </button>\n  `).join(\"\");\n}\n\nfunction buildStudentAvailability() {\n  return weekdays.map((day) => ({\n    day: day.id,\n    label: day.label,\n    slots: studentSlots.map((slot) => ({\n      slot: slot.id,\n      time: slot.label,\n      available: state.student.has(`${day.id}_${slot.id}`),\n    })),\n  }));\n}\n\nfunction buildTeacherAvailability() {\n  return teacherDays.map((day) => ({\n    day: day.id,\n    label: day.label,\n    time: day.time,\n    available: state.teacher.has(day.id),\n  }));\n}\n\nasync function sha256Hex(value) {\n  const bytes = new TextEncoder().encode(value);\n  const digest = await crypto.subtle.digest(\"SHA-256\", bytes);\n  return [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, \"0\")).join(\"\");\n}\n\nasync function fetchProfile(token) {\n  const response = await fetch(functionUrl(`?token=${encodeURIComponent(token)}`), {\n    method: \"GET\",\n    headers: { Accept: \"application/json\" },\n    cache: \"no-store\",\n  });\n  if (!response.ok) throw new Error(\"この回答URLは無効か、期限が切れています。管理者へ連絡してください。\");\n  const data = await response.json();\n  return data.profile;\n}\n\nasync function submitSurvey(availability, memo) {\n  const response = await fetch(functionUrl(), {\n    method: \"POST\",\n    headers: { \"Content-Type\": \"application/json\", Accept: \"application/json\" },\n    body: JSON.stringify({ token: state.token, availability, memo }),\n  });\n  const data = await response.json().catch(() => ({}));\n  if (response.status === 409) {\n    throw new Error(\"回答済みです。変更が必要な場合は管理者へ連絡してください。\");\n  }\n  if (!response.ok) throw new Error(data.message || \"時間をおいて、もう一度お試しください。\");\n  return data;\n}\n\nfunction formatAvailability(row) {\n  const availability = row.availability ?? [];\n  if (row.role === \"teacher\") {\n    return availability.filter((day) => day.available).map((day) => `${day.label} ${day.time}`).join(\" / \");\n  }\n  return availability.map((day) => {\n    const slots = day.slots.filter((slot) => slot.available).map((slot) => slot.time);\n    return slots.length ? `${day.label}: ${slots.join(\", \")}` : \"\";\n  }).filter(Boolean).join(\" / \");\n}\n\nfunction formatDate(value) {\n  if (!value) return \"\";\n  const date = new Date(value);\n  if (Number.isNaN(date.getTime())) return \"\";\n  return new Intl.DateTimeFormat(\"ja-JP\", {\n    timeZone: \"Asia/Tokyo\",\n    month: \"2-digit\",\n    day: \"2-digit\",\n    hour: \"2-digit\",\n    minute: \"2-digit\",\n    hour12: false,\n  }).format(date);\n}\n\nfunction tokenSubmissionKey() {\n  return `${localSubmissionPrefix}:token:${state.tokenStorageKey}`;\n}\n\nfunction legacySubmissionKey() {\n  return `${localSubmissionPrefix}:${state.profile.role}:${state.profile.respondentName}`;\n}\n\nfunction saveLocalSubmission(submission) {\n  try {\n    localStorage.setItem(tokenSubmissionKey(), JSON.stringify(submission));\n  } catch {\n    // Local answer review is optional; the server submission has already succeeded.\n  }\n}\n\nfunction readLocalSubmission() {\n  try {\n    const current = localStorage.getItem(tokenSubmissionKey());\n    if (current) return JSON.parse(current);\n    const legacy = localStorage.getItem(legacySubmissionKey());\n    return legacy ? JSON.parse(legacy) : null;\n  } catch {\n    return null;\n  }\n}\n\nfunction renderOwnAnswer(role, submission) {\n  const element = role === \"student\" ? elements.studentReview : elements.teacherReview;\n  if (!submission) {\n    element.innerHTML = \"\";\n    return;\n  }\n  element.innerHTML = `\n    <div class=\"own-answer-title\">前回送信した内容</div>\n    <table>\n      <tbody>\n        <tr><th>回答日時</th><td>${formatDate(submission.created_at)}</td></tr>\n        <tr><th>可能日時</th><td>${escapeHtml(formatAvailability(submission) || \"なし\")}</td></tr>\n        <tr><th>補足</th><td>${escapeHtml(submission.memo ?? \"\")}</td></tr>\n      </tbody>\n    </table>\n  `;\n}\n\nfunction applyStudentSubmission(submission) {\n  state.student = new Set(\n    (submission.availability ?? []).flatMap((day) =>\n      (day.slots ?? []).filter((slot) => slot.available).map((slot) => `${day.day}_${slot.slot}`)\n    )\n  );\n  document.querySelector(\"#studentMemo\").value = submission.memo ?? \"\";\n  renderStudentGrid();\n}\n\nfunction applyTeacherSubmission(submission) {\n  state.teacher = new Set(\n    (submission.availability ?? []).filter((day) => day.available).map((day) => day.day)\n  );\n  document.querySelector(\"#teacherMemo\").value = submission.memo ?? \"\";\n  renderTeacherGrid();\n}\n\nfunction renderProfile(profile) {\n  if (profile.role === \"student\") {\n    elements.studentIdentityName.textContent = profile.respondentName;\n    elements.studentIdentityGrade.textContent = profile.grade || \"学年未設定\";\n  } else {\n    elements.teacherIdentityName.textContent = profile.respondentName;\n  }\n}\n\nfunction escapeHtml(value) {\n  return String(value ?? \"\")\n    .replaceAll(\"&\", \"&amp;\")\n    .replaceAll(\"<\", \"&lt;\")\n    .replaceAll(\">\", \"&gt;\")\n    .replaceAll('\"', \"&quot;\")\n    .replaceAll(\"'\", \"&#039;\");\n}\n\nelements.studentGrid.addEventListener(\"click\", (event) => {\n  const key = event.target.dataset.studentSlot;\n  if (!key) return;\n  if (state.student.has(key)) state.student.delete(key);\n  else state.student.add(key);\n  renderStudentGrid();\n});\n\nelements.teacherGrid.addEventListener(\"click\", (event) => {\n  const button = event.target.closest(\"[data-teacher-day]\");\n  if (!button) return;\n  const key = button.dataset.teacherDay;\n  if (state.teacher.has(key)) state.teacher.delete(key);\n  else state.teacher.add(key);\n  renderTeacherGrid();\n});\n\nelements.studentForm.addEventListener(\"submit\", async (event) => {\n  event.preventDefault();\n  const availability = buildStudentAvailability();\n  const memo = document.querySelector(\"#studentMemo\").value.trim();\n  if (!state.student.size) {\n    showStatus(\"通塾できる日時を1つ以上〇のまま残してください。\", \"error\");\n    return;\n  }\n  showStatus(\"送信中です...\");\n  try {\n    const result = await submitSurvey(availability, memo);\n    const submission = {\n      role: \"student\",\n      respondent_name: state.profile.respondentName,\n      grade: state.profile.grade,\n      availability,\n      memo,\n      created_at: result.createdAt,\n    };\n    saveLocalSubmission(submission);\n    renderOwnAnswer(\"student\", submission);\n    showStatus(\"送信しました。\");\n  } catch (error) {\n    showStatus(`送信できませんでした。${error.message}`, \"error\");\n  }\n});\n\nelements.teacherForm.addEventListener(\"submit\", async (event) => {\n  event.preventDefault();\n  const availability = buildTeacherAvailability();\n  const memo = document.querySelector(\"#teacherMemo\").value.trim();\n  if (!state.teacher.size) {\n    showStatus(\"勤務できる曜日を1つ以上選択してください。\", \"error\");\n    return;\n  }\n  showStatus(\"送信中です...\");\n  try {\n    const result = await submitSurvey(availability, memo);\n    const submission = {\n      role: \"teacher\",\n      respondent_name: state.profile.respondentName,\n      grade: null,\n      availability,\n      memo,\n      created_at: result.createdAt,\n    };\n    saveLocalSubmission(submission);\n    renderOwnAnswer(\"teacher\", submission);\n    showStatus(\"送信しました。\");\n  } catch (error) {\n    showStatus(`送信できませんでした。${error.message}`, \"error\");\n  }\n});\n\nasync function initialize() {\n  selectAllStudentSlots();\n  renderStudentGrid();\n  renderTeacherGrid();\n\n  const queryToken = new URLSearchParams(location.search).get(\"token\")?.trim() || \"\";\n  const storedToken = sessionStorage.getItem(sessionTokenKey) || \"\";\n  const token = queryToken || storedToken;\n  if (!tokenPattern.test(token)) {\n    sessionStorage.removeItem(sessionTokenKey);\n    showAccessState(\"専用URLが必要です\", \"管理者から案内された回答URLを開いてください。\", \"error\");\n    return;\n  }\n\n  if (queryToken) {\n    sessionStorage.setItem(sessionTokenKey, queryToken);\n    history.replaceState(null, \"\", location.pathname);\n  }\n\n  state.token = token;\n  state.tokenStorageKey = await sha256Hex(token);\n  showAccessState(\"回答ページを確認しています\", \"少しお待ちください。\");\n  try {\n    const profile = await fetchProfile(token);\n    if (!profile || ![\"student\", \"teacher\"].includes(profile.role)) throw new Error(\"invalid profile\");\n    state.profile = profile;\n    renderProfile(profile);\n    showPage(profile.role);\n\n    const localSubmission = readLocalSubmission();\n    if (localSubmission) {\n      if (profile.role === \"student\") applyStudentSubmission(localSubmission);\n      else applyTeacherSubmission(localSubmission);\n      renderOwnAnswer(profile.role, localSubmission);\n    }\n  } catch {\n    sessionStorage.removeItem(sessionTokenKey);\n    state.token = \"\";\n    showAccessState(\"回答ページを開けません\", \"この回答URLは無効か、期限が切れています。管理者へ連絡してください。\", \"error\");\n  }\n}\n\ninitialize();\n","type":"application/javascript; charset=utf-8"}};

export default {
  async fetch(request) {
    const url = new URL(request.url);
    const path = url.pathname === "/" ? "/index.html" : url.pathname;
    const asset = ASSETS[path] || ASSETS["/index.html"];
    return new Response(asset.body, {
      headers: {
        "content-type": asset.type,
        "cache-control": "no-store",
      },
    });
  },
};
